static const z_t5517_t _zag1588 = { { .data = "chan_receive", .size = 12 }, { .length = 1, .data = _zag1586 }, { .length = 5, .data = _zag1587 }, { .data = "/* the oldest value, moved to `out`: true when there was one. `wait` waits for\n   one while a Sender lives; without it an empty ring answers false at once */\nstatic bool z_chan_receive(z_chan* b, void* out, bool wait) {\n    z_mutex_lock(&b->m);\n    while (wait && b->len == 0 && b->senders > 0) z_cond_wait(&b->notEmpty, &b->m);\n    if (b->len == 0) {\n        z_mutex_unlock(&b->m);\n        return false;\n    }\n    memcpy(out, b->ring + b->head * b->elemSize, b->elemSize);\n    b->head = (b->head + 1) % b->size;\n    b->len--;\n    z_cond_signal(&b->notFull);\n    z_mutex_unlock(&b->m);\n    return true;\n}", .size = 604 } };
