static const z_t5702_t _zag3310 = { { .data = "create", .size = 6 }, { .data = "", .size = 0 }, { .length = 2, .data = _zag3309 }, { .data = "static z_@@NAME@@_t z_@@NAME@@_create(z_@@ARG.create.task@@_t task, @@StringView@@_t name, uint64_t stackSize) {\n    z_@@NAME@@_t h;\n    h.b = (z_@@NAME@@_blk*)z_xmalloc(sizeof(z_@@NAME@@_blk));\n    memset(h.b, 0, sizeof(z_@@NAME@@_blk));\n    h.b->task = task;\n    char nm[16];\n    size_t n = name.size < 15 ? (size_t)name.size : 15;\n    memcpy(nm, name.data, n);\n    nm[n] = 0;\n    if (z_thread_start(&h.b->th, z_@@NAME@@_run, h.b, stackSize, nm) != 0) {\n        z_panic(\"thread.spawn: the operating system could not start a thread\");\n    }\n    return h;\n}", .size = 557 } };
